import{_ as i}from"./chunks/zeugnisdruck-zeugniseinstellungen-ini.Chrj5pMy.js";import{_ as d,o as s,c as o,a3 as t,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const c="/bilder/zeugnisformulare/zeugnisdruck-zeugniseinstellungen-ini-editor.png",A=JSON.parse('{"title":"Inhalt und Layout von Zeugnissen konfigurieren","description":"","frontmatter":{"title":"Inhalt und Layout von Zeugnissen konfigurieren","pageClass":"zeugnisoptionen","source_pageid":1618,"source_revision":6791},"headers":[],"relativePath":"reporting/zeugnisformulare/inhalt-layout-von-zeugnissen-konfigurieren.md","filePath":"reporting/zeugnisformulare/inhalt-layout-von-zeugnissen-konfigurieren.md"}'),u={name:"reporting/zeugnisformulare/inhalt-layout-von-zeugnissen-konfigurieren.md"};function a(l,r,g,h,m,f){return s(),o("div",null,[...r[0]||(r[0]=[t('<h1 id="inhalt-und-layout-von-zeugnissen-konfigurieren" tabindex="-1">Inhalt und Layout von Zeugnissen konfigurieren <a class="header-anchor" href="#inhalt-und-layout-von-zeugnissen-konfigurieren" aria-label="Permalink to &quot;Inhalt und Layout von Zeugnissen konfigurieren&quot;">​</a></h1><p>Passen Sie die Datei Zeugniseinstellungen.ini für die verwendeten Zeugnisanlagen an. Die Einstellungen gelten jeweils für die zugehörige Anlage und müssen nicht in jedem Formular verfügbar sein.</p><h2 id="die-einstellungsdatei-vorbereiten" tabindex="-1">Die Einstellungsdatei vorbereiten <a class="header-anchor" href="#die-einstellungsdatei-vorbereiten" aria-label="Permalink to &quot;Die Einstellungsdatei vorbereiten&quot;">​</a></h2><p>Nun sollte noch die Einstellungsdatei <em>Zeugniseinstellungen.ini</em> konfiguriert werden und dann sind die Zeugnisse verwendbar.</p><h3 id="aufbau-der-ini-datei" tabindex="-1">Aufbau der INI-Datei <a class="header-anchor" href="#aufbau-der-ini-datei" aria-label="Permalink to &quot;Aufbau der INI-Datei&quot;">​</a></h3><p><a href="/bilder/zeugnisformulare/zeugnisdruck-zeugniseinstellungen-ini.png"><img src="'+i+'" alt="Die Zeugniseinstellungen.ini kann direkt aus dem Reportexplorer geöffnet werden." loading="lazy"></a></p><p><em>Die Zeugniseinstellungen.ini kann direkt aus dem Reportexplorer geöffnet werden.</em></p><p>Die Zeugnisse können - und müssen - über Einstellungen in der Datei <em>Zeugniseinstellungen.ini</em> konfiguriert werden. Es öffnet sich der in Ihrem Windows eingestellte Texteditor.</p>',8),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Die "),e("em",null,"Zeugniseinstellungen.ini"),n(" muss im gleichen Verzeichnis liegen wie die Zeugnisformulare, die sie steuert.")])],-1),t('<p><a href="/bilder/zeugnisformulare/zeugnisdruck-zeugniseinstellungen-ini-editor.png"><img src="'+c+'" alt="Die Zeugniseinstellungen.ini im Windows-Editor." loading="lazy"></a></p><p><em>Die Zeugniseinstellungen.ini im Windows-Editor.</em></p><p>Die Datei ist wie folgt aufgebaut: Alle Zeilen, die mit einem &quot;<strong>;</strong>&quot; beginnen, sind <em>Kommentare</em> und werden damit nicht maschinell verarbeitet, sondern sind Erklärungen für den Menschen.</p><p>Beispiel:</p><blockquote><p>; Zeilen, die mit einem Semikolon beginnen sind Kommentare und werden ignoriert.</p></blockquote><p>Zeilen, die einen Block mit einem Wort in [Eckigen Klammern] einleiten, gelten für eine bestimmte Zeugnisanlage. Typischerweise befindet sich darüber eine Zeile mit einem Kommentar, die erläutert, um was für eine Anlage es sich handelt.</p><p>Beispiel:</p><blockquote><p>; Anlage 03: Regulares Halbjahres- und Versetzungszeugnis EF</p><p>[Anlage03]</p></blockquote><p>Die folgenden Zeilen steuern das Verhalten des Zeugnisformulars. Jede Zeile hat den Aufbau <strong>Option=Wert</strong>. <strong>J</strong> bedeutet „Ja“, <strong>N</strong> bedeutet „Nein“. Wenn das Zeugnis ohne Rand gedruckt werden soll, setzen Sie die Option <strong>ZeugnisMitRand</strong> in der INI-Datei wie folgt:</p><blockquote><p>ZeugnisMitRand=N</p></blockquote><p>Für ein Zeugnis <em>mit</em> Rand wäre somit zu setzen:</p><blockquote><p>ZeugnisMitRand=J</p></blockquote><p>Am Ende der Datei, unter den Einstellungen für alle von ihr gesteuerten Zeugnisformulare, folgt eine Erklärung aller möglichen <em>Optionen</em> (vor dem &quot;=&quot;) und der jeweils zugelassenen Konfiguration (nach dem &quot;=&quot;). Die Konfiguration ist oftmals nur ein <em>Buchstabe</em>, kann aber auch <em>Texte</em> enthalten.</p>',13),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,[n("Diese Eintragungen sind für jedes Zeugnisformular - z.B. jede "),e("em",null,"Anlage"),n(", gesondert einzustellen!")])],-1),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,[n("Sollen also alle Zeugnisse mit Rand gedruckt werden, wäre für alle von einer "),e("em",null,"Zeugniseinstellungen.ini"),n(" verwalteten Formulare jeweils die Option "),e("em",null,"ZeugnisMitRand"),n(" das "),e("em",null,"N"),n(" zu einem "),e("em",null,"J"),n(" zu ändern.")])],-1),e("h3",{id:"zeugnisoptionen-und-ihre-einstellmoglichkeiten",tabindex:"-1"},[n("Zeugnisoptionen und ihre Einstellmöglichkeiten "),e("a",{class:"header-anchor",href:"#zeugnisoptionen-und-ihre-einstellmoglichkeiten","aria-label":'Permalink to "Zeugnisoptionen und ihre Einstellmöglichkeiten"'},"​")],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Nicht alle möglichen Optionen werden in allen Zeugnisformularen genutzt.")],-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n('Nutzen Sie in Ihrem Texteditor die Funktion "Suchen und Ersetzen", um alle Einträge in einer Datei zu ändern. Wollen Sie zum Beispiel alle Zeugnisse ohne Amtsbezeichnungen drucken, suchen Sie nach '),e("em",null,"UnterschriftenMitAmtsbezeichnungen=J"),n(" und ersetzen Sie alle Vorkommnisse durch "),e("em",null,"UnterschriftenMitAmtsbezeichnungen=N"),n(".")])],-1),t('<p>Diese Tabelle dient der Übersichtlichkeit, möglicherweise bietet ein bestimmtes Zeugnisformular noch weitere Optionen an. Diese wären dann dem Fuß der jeweiligen <em>Zeugniseinstellungen.ini</em> zu entnehmen.</p><p><strong>Einstellen von Zeugnisformularen</strong></p><p>Jede Zeile zeigt eine vollständige Einstellung und ihre Wirkung. Bei frei wählbaren Werten sind Beispiele oder Platzhalter wie <code>Text</code>, <code>Angabe</code> und <code>R,G,B</code> angegeben. Ersetzen Sie diese durch die benötigten Angaben. Ein Eintrag, der direkt nach dem Gleichheitszeichen endet, steht für einen leeren Wert.</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wirkung</th></tr></thead><tbody><tr><td><code>ZeugnisMitRand=J</code></td><td>Druckt das Zeugnis mit Rand.</td></tr><tr><td><code>ZeugnisMitRand=N</code></td><td>Druckt das Zeugnis ohne Rand.</td></tr><tr><td><code>A3ZeugnisSeiten14Ausblenden=J</code></td><td>Druckt bei einem A3-Zeugnis nur die inneren Seiten 2 und 3. Die Seiten 1 und 4 werden ausgeblendet; gleichzeitig wird der Duplexdruck deaktiviert.</td></tr><tr><td><code>A3ZeugnisSeiten14Ausblenden=N</code></td><td>Druckt alle Seiten des A3-Zeugnisses im Duplexdruck.</td></tr><tr><td><code>FarbeNotenfeld=R,G,B</code></td><td>Legt die Hintergrundfarbe der Notenfelder mit den Farbanteilen Rot, Grün und Blau fest. Jeder Wert muss eine ganze Zahl von 0 bis 255 sein, zum Beispiel <code>255,20,170</code>. Der Standardwert <code>192,192,192</code> ergibt Grau.</td></tr><tr><td><code>ZeugnisVorname=V</code></td><td>Verwendet für den Zeugnisvornamen nur das Feld „Vorname“.</td></tr><tr><td><code>ZeugnisVorname=W</code></td><td>Verwendet das Feld „Vorname“ und hängt den Inhalt von „Weitere Vornamen“ an. Ist „Weitere Vornamen“ leer, wird nur „Vorname“ verwendet.</td></tr><tr><td><code>ZeugnisVorname=A</code></td><td>Verwendet nur „Weitere Vornamen“; dieses Feld muss dann alle gewünschten Vornamen enthalten. Ist es leer, wird stattdessen „Vorname“ verwendet.</td></tr><tr><td><code>ZeugnisDatumQuelle=Z</code></td><td>Verwendet das Zeugnisdatum des aktuellen Lernabschnitts als Zeugnisdatum.</td></tr><tr><td><code>ZeugnisDatumQuelle=K</code></td><td>Verwendet das Konferenzdatum des aktuellen Lernabschnitts als Zeugnisdatum.</td></tr><tr><td><code>ZeugnisDatumQuelle=V</code></td><td>Verwendet normalerweise das Zeugnisdatum des aktuellen Lernabschnitts. Bei nicht versetzten Schülerinnen und Schülern im zweiten Halbjahr wird stattdessen das Konferenzdatum verwendet.</td></tr><tr><td><code>ZeugnisDatumQuelle=E</code></td><td>Verwendet das in SchILD hinterlegte Entlassdatum als Zeugnisdatum.</td></tr><tr><td><code>ZeugnisDatumQuelle=S</code></td><td>Verwendet das in SchILD hinterlegte Schulwechseldatum als Zeugnisdatum.</td></tr><tr><td><code>ZeugnisDatumQuelle=A</code></td><td>Verwendet das aktuelle Tagesdatum als Zeugnisdatum.</td></tr><tr><td><code>ZeugnisDatumQuelle=I</code></td><td>Verwendet das Datum, das in derselben INI-Datei unter <code>ZeugnisDatumAngabe</code> eingetragen ist.</td></tr><tr><td><code>ZeugnisDatumQuelle=F</code></td><td>Öffnet beim Aufruf des Formulars ein Eingabefenster, in dem das Zeugnisdatum angegeben wird.</td></tr><tr><td><code>ZeugnisDatumQuelle=</code></td><td>Ein leerer Wert öffnet einen Auswahldialog zur Ermittlung des Zeugnisdatums.</td></tr><tr><td><code>ZeugnisDatumAngabe=28.07.24</code></td><td>Gibt das Zeugnisdatum im Kurzformat vor, hier beispielhaft den 28. Juli 2024. Diese Angabe wird nur bei <code>ZeugnisDatumQuelle=I</code> verwendet.</td></tr><tr><td><code>ZeugnisInformationenQuelle=F</code></td><td>Fragt die Angaben zum Wiederanfang des Unterrichts und zum Elternsprechtag beim Aufruf des Formulars ab.</td></tr><tr><td><code>ZeugnisInformationenQuelle=I</code></td><td>Liest die Angaben zum Wiederanfang des Unterrichts und zum Elternsprechtag aus der INI-Datei. Für den Wiederanfang dient <code>ZeugnisInformationenWiederanfangAngabe</code>.</td></tr><tr><td><code>ZeugnisInformationenQuelle=D</code></td><td>Sieht vor, die Angaben zum Wiederanfang des Unterrichts und zum Elternsprechtag aus der Datenbank zu lesen. Die übernommene Beschreibung kennzeichnet diese Funktion als noch nicht implementiert.</td></tr><tr><td><code>ZeugnisInformationenQuelle=</code></td><td>Ein leerer Wert bewirkt, dass die Informationen zum Wiederanfang des Unterrichts und zum Elternsprechtag ignoriert werden.</td></tr><tr><td><code>ZeugnisInformationenWiederanfangAngabe=1. August 2024 um 08:00 Uhr</code></td><td>Gibt den Text mit Datum und Uhrzeit für den Wiederanfang des Unterrichts vor. Die Angabe wird nur bei <code>ZeugnisInformationenQuelle=I</code> verwendet.</td></tr><tr><td><code>UnterschriftenSLAL=S</code></td><td>Verwendet die Daten der Schulleitung aus der Datenbank für das Unterschriftenfeld der Schul- oder Abteilungsleitung.</td></tr><tr><td><code>UnterschriftenSLAL=V</code></td><td>Verwendet die Daten der stellvertretenden Schulleitung aus der Datenbank für das Unterschriftenfeld der Schul- oder Abteilungsleitung.</td></tr><tr><td><code>UnterschriftenSLAL=A</code></td><td>Verwendet die Daten der Abteilungsleitung aus der Datenbank für das Unterschriftenfeld der Schul- oder Abteilungsleitung.</td></tr><tr><td><code>UnterschriftenSLAL=I</code></td><td>Übernimmt den unter <code>UnterschriftenSLALText</code> hinterlegten Text ohne Rückfrage beim Zeugnisdruck.</td></tr><tr><td><code>UnterschriftenSLAL=T</code></td><td>Fragt den Text beim Zeugnisdruck ab. Der unter <code>UnterschriftenSLALText</code> hinterlegte Text ist vorbelegt und kann bei der Zeugnisgenerierung geändert werden.</td></tr><tr><td><code>UnterschriftenSLALText=MUST,(Schulleiterin)</code></td><td>Verwendet die Lehrkraft mit dem Kürzel <code>MUST</code> und ergänzt die Funktionsbezeichnung „Schulleiterin“. Allgemeines Format: <code>KÜRZEL,(mein Text)</code>; der Zusatz ist optional. Der Name wird gemäß den Namenseinstellungen ausgegeben. Der Eintrag wird bei <code>UnterschriftenSLAL=I</code> direkt verwendet und bei <code>UnterschriftenSLAL=T</code> zur Änderung vorbelegt. Ein senkrechter Strich (<code>|</code>, „Pipe“) im Text erzeugt einen Zeilenumbruch.</td></tr><tr><td><code>UnterschriftenSLALText=Marie Musterfrau, Stv. Konrektorin</code></td><td>Druckt diesen frei gewählten Text wörtlich unter die Unterschriftenlinie der Schul- oder Abteilungsleitung. Er wird bei <code>UnterschriftenSLAL=I</code> direkt verwendet und bei <code>UnterschriftenSLAL=T</code> zur Änderung vorbelegt. Ein senkrechter Strich (<code>|</code>, „Pipe“) im Text erzeugt einen Zeilenumbruch.</td></tr><tr><td><code>UnterschriftenKL=K</code></td><td>Verwendet die Klassenleitung aus der Datenbank für das Unterschriftenfeld der Klassenleitung.</td></tr><tr><td><code>UnterschriftenKL=I</code></td><td>Übernimmt den unter <code>UnterschriftenKLText</code> hinterlegten Text ohne Rückfrage beim Zeugnisdruck.</td></tr><tr><td><code>UnterschriftenKL=T</code></td><td>Fragt den Text für die Klassenleitungsunterschrift beim Aufruf des Zeugnisses ab. <code>UnterschriftenKLText</code> legt die Vorbelegung fest.</td></tr><tr><td><code>UnterschriftenKLText=MUST,(Beratungslehrer)</code></td><td>Verwendet die Lehrkraft mit dem Kürzel <code>MUST</code> und dem optionalen Zusatz „Beratungslehrer“; ein weiteres Beispiel ist <code>MUST,(Koordinator SII)</code>. Der Name wird gemäß den Namenseinstellungen ausgegeben. Der Eintrag wird bei <code>UnterschriftenKL=I</code> direkt verwendet und bei <code>UnterschriftenKL=T</code> zur Änderung vorbelegt.</td></tr><tr><td><code>UnterschriftenKLText=Text</code></td><td>Verwendet einen frei gewählten Text wörtlich für das Unterschriftenfeld der Klassenleitung. Er wird bei <code>UnterschriftenKL=I</code> direkt verwendet und bei <code>UnterschriftenKL=T</code> zur Änderung vorbelegt.</td></tr><tr><td><code>UnterschriftenVorsitzZAA=S</code></td><td>Verwendet die Schulleitung aus der Datenbank für die Unterschrift des Vorsitzes des Zentralen Abiturausschusses.</td></tr><tr><td><code>UnterschriftenVorsitzZAA=V</code></td><td>Verwendet die stellvertretende Schulleitung aus der Datenbank für die Unterschrift des Vorsitzes des Zentralen Abiturausschusses.</td></tr><tr><td><code>UnterschriftenVorsitzZAA=I</code></td><td>Übernimmt den in der INI-Datei hinterlegten Text für den ZAA-Vorsitz ohne Rückfrage beim Zeugnisdruck; siehe <code>UnterschriftenVorsitzZAAText</code>.</td></tr><tr><td><code>UnterschriftenVorsitzZAA=T</code></td><td>Fragt den Text für die Unterschrift des ZAA-Vorsitzes beim Aufruf des Zeugnisses ab. <code>UnterschriftenVorsitzZAAText</code> legt die Vorbelegung fest.</td></tr><tr><td><code>UnterschriftenVorsitzZAAText=MUST,(Vorsitz ZAA)</code></td><td>Verwendet die Lehrkraft mit dem Kürzel <code>MUST</code> und dem optionalen Zusatz „Vorsitz ZAA“. Der Name wird gemäß den Namenseinstellungen ausgegeben. Der Eintrag wird bei <code>UnterschriftenVorsitzZAA=I</code> direkt verwendet und bei <code>UnterschriftenVorsitzZAA=T</code> zur Änderung vorbelegt. Ein senkrechter Strich (<code>|</code>, „Pipe“) im Text erzeugt einen Zeilenumbruch.</td></tr><tr><td><code>UnterschriftenVorsitzZAAText=i.V. Maxi Muster (GeD)</code></td><td>Verwendet diesen frei gewählten Text wörtlich für die Unterschrift des ZAA-Vorsitzes. Er wird bei <code>UnterschriftenVorsitzZAA=I</code> direkt verwendet und bei <code>UnterschriftenVorsitzZAA=T</code> zur Änderung vorbelegt. Ein senkrechter Strich (<code>|</code>, „Pipe“) im Text erzeugt einen Zeilenumbruch.</td></tr><tr><td><code>UnterschriftenSchultraegerText=Dr. Glitzerfee, Gemeinde Einhornlichtung</code></td><td>Verwendet diesen frei gewählten Text als Unterschriftenbezeichnung der Vertretung des Schulträgers auf dem Abiturzeugnis. Ein senkrechter Strich (<code>|</code>, „Pipe“) im Text erzeugt einen Zeilenumbruch.</td></tr><tr><td><code>UnterschriftenFunktionZeilenumbruch=J</code></td><td>Setzt die Funktionsbezeichnung bei Unterschriften in eine neue Zeile: beispielsweise „Meier,“ und darunter „Abteilungsleiter“. Gilt nicht bei der Ausgabe des stellvertretenden Beratungslehrers; bei <code>UnterschriftenMitStvKlassenlehrer=J</code> wird diese Einstellung ebenfalls nicht beachtet.</td></tr><tr><td><code>UnterschriftenFunktionZeilenumbruch=N</code></td><td>Setzt Name und Funktionsbezeichnung in dieselbe Zeile, beispielsweise „Meier, Abteilungsleiter“. Gilt nicht bei der Ausgabe des stellvertretenden Beratungslehrers; bei <code>UnterschriftenMitStvKlassenlehrer=J</code> wird diese Einstellung ebenfalls nicht beachtet.</td></tr><tr><td><code>UnterschriftenMitNachnamen=J</code></td><td>Verwendet die Nachnamen der betreffenden Personen anstelle allgemeiner Bezeichnungen der Unterschriftenfelder.</td></tr><tr><td><code>UnterschriftenMitNachnamen=N</code></td><td>Verwendet allgemeine Bezeichnungen der Unterschriftenfelder. Vornamen, Titel und Amtsbezeichnungen werden ebenfalls nicht ausgegeben; die zugehörigen Namensoptionen werden ignoriert.</td></tr><tr><td><code>UnterschriftenMitAmtsbezeichnungen=J</code></td><td>Ergänzt die Amtsbezeichnung bei Unterschriften, sofern <code>UnterschriftenMitNachnamen=J</code> gesetzt ist.</td></tr><tr><td><code>UnterschriftenMitAmtsbezeichnungen=N</code></td><td>Ergänzt keine Amtsbezeichnung bei Unterschriften.</td></tr><tr><td><code>UnterschriftenMitVornamen=J</code></td><td>Ergänzt die Anfangsbuchstaben der Vornamen bei Unterschriften, sofern <code>UnterschriftenMitNachnamen=J</code> gesetzt ist.</td></tr><tr><td><code>UnterschriftenMitVornamen=N</code></td><td>Ergänzt keine Anfangsbuchstaben der Vornamen bei Unterschriften.</td></tr><tr><td><code>UnterschriftenMitVornamenNurErster=J</code></td><td>Berücksichtigt bei <code>UnterschriftenMitVornamen=J</code> nur den ersten Vornamen. Die Namensausgabe setzt außerdem <code>UnterschriftenMitNachnamen=J</code> voraus.</td></tr><tr><td><code>UnterschriftenMitVornamenNurErster=N</code></td><td>Beschränkt die Anfangsbuchstaben bei <code>UnterschriftenMitVornamen=J</code> nicht auf den ersten Vornamen. Die Namensausgabe setzt außerdem <code>UnterschriftenMitNachnamen=J</code> voraus.</td></tr><tr><td><code>UnterschriftenMitTitel=J</code></td><td>Ergänzt einen Titel bei Unterschriften, typischerweise einen Doktortitel, sofern <code>UnterschriftenMitNachnamen=J</code> gesetzt ist.</td></tr><tr><td><code>UnterschriftenMitTitel=N</code></td><td>Ergänzt keinen Titel bei Unterschriften.</td></tr><tr><td><code>UnterschriftenMitStvKlassenlehrer=J</code></td><td>Gibt auch den stellvertretenden Klassenlehrer im Unterschriftenbereich aus. Die Einstellung <code>UnterschriftenFunktionZeilenumbruch</code> wird dabei nicht beachtet.</td></tr><tr><td><code>UnterschriftenMitStvKlassenlehrer=N</code></td><td>Gibt den stellvertretenden Klassenlehrer nicht zusätzlich im Unterschriftenbereich aus.</td></tr><tr><td><code>AnschreibenRuecksendeangaben=Text</code></td><td>Nur für Anschreiben: Gibt eigene Rücksendeangaben vor.</td></tr><tr><td><code>AnschreibenRuecksendeangaben=</code></td><td>Nur für Anschreiben: Bei leerem Wert werden die Angaben aus der Datenbank verwendet, sofern der Report keine feste Eintragung enthält.</td></tr><tr><td><code>AnschreibenVermerkzone=Text</code></td><td>Nur für Anschreiben: Gibt einen eigenen Text für die Vermerkzone vor.</td></tr><tr><td><code>AnschreibenVermerkzone=</code></td><td>Nur für Anschreiben: Bei leerem Wert werden die Angaben aus dem Report verwendet.</td></tr><tr><td><code>AnschreibenInfoblockNameFunktionQuelle=U</code></td><td>Nur für Anschreiben: Übernimmt Name und Funktion im rechten Infoblock von der Person des Unterschriftenfeldes.</td></tr><tr><td><code>AnschreibenInfoblockNameFunktionQuelle=I</code></td><td>Nur für Anschreiben: Übernimmt Name und Funktion im rechten Infoblock aus den entsprechenden Einträgen der INI-Datei.</td></tr><tr><td><code>AnschreibenInfoblockNameFunktionQuelle=K</code></td><td>Nur für Anschreiben: Blendet den Infoblock aus.</td></tr><tr><td><code>AnschreibenInfoblockName=Text</code></td><td>Nur für Anschreiben: Hinterlegt den Namen für den Infoblock. Die Verwendung wird durch <code>AnschreibenInfoblockNameFunktionQuelle</code> gesteuert.</td></tr><tr><td><code>AnschreibenInfoblockFunktion=Text</code></td><td>Nur für Anschreiben: Hinterlegt die Funktionsbezeichnung für den Infoblock. Die Verwendung wird durch <code>AnschreibenInfoblockNameFunktionQuelle</code> gesteuert.</td></tr><tr><td><code>AnschreibenInfoblockTelefon=Text</code></td><td>Nur für Anschreiben: Hinterlegt die Telefonnummer für den Infoblock. Die Verwendung wird durch <code>AnschreibenInfoblockNameFunktionQuelle</code> gesteuert.</td></tr><tr><td><code>AnschreibenInfoblockFax=Text</code></td><td>Nur für Anschreiben: Hinterlegt die Faxnummer für den Infoblock. Die Verwendung wird durch <code>AnschreibenInfoblockNameFunktionQuelle</code> gesteuert.</td></tr><tr><td><code>AnschreibenInfoblockWeb=Text</code></td><td>Nur für Anschreiben: Hinterlegt die Webadresse für den Infoblock. Die Verwendung wird durch <code>AnschreibenInfoblockNameFunktionQuelle</code> gesteuert.</td></tr><tr><td><code>AnschreibenInfoblockEMail=Text</code></td><td>Nur für Anschreiben: Hinterlegt die E-Mail-Adresse für den Infoblock. Die Verwendung wird durch <code>AnschreibenInfoblockNameFunktionQuelle</code> gesteuert.</td></tr><tr><td><code>AnschreibenDatumsangabe1=Angabe</code></td><td>Nur für Anschreiben: Hinterlegt die erste dynamische Datumsangabe.</td></tr><tr><td><code>AnschreibenDatumsangabe2=Angabe</code></td><td>Nur für Anschreiben: Hinterlegt die zweite dynamische Datumsangabe.</td></tr><tr><td><code>AnschreibenFreitext=Text</code></td><td>Nur für Anschreiben: Hinterlegt dynamischen Freitext.</td></tr><tr><td><code>SchulabschlussQuelle=H</code></td><td>Verwendet für das Abschlusszeugnis den Eintrag des Schulabschlusses im aktuellen Halbjahr.</td></tr><tr><td><code>SchulabschlussQuelle=L</code></td><td>Sieht vor, den Schulabschluss aus der Liste der Abschlüsse in SchILD zu übernehmen. Die übernommene Beschreibung kennzeichnet diese Liste als noch nicht implementiert.</td></tr><tr><td><code>SchulabschlussQuelle=F</code></td><td>Fragt den Schulabschluss beim Aufruf des Formulars ab.</td></tr><tr><td><code>AlteAbschluesseErfragen=J</code></td><td>Fragt beim Druck eines Abgangszeugnisses nach früheren Abschlüssen, wenn der zugehörige Abschluss nicht gefunden wurde. Das kann zum Beispiel Personen betreffen, die bereits mit einem Abschluss aufgenommen wurden und die Schule ohne einen höherwertigen Abschluss verlassen.</td></tr><tr><td><code>AlteAbschluesseErfragen=N</code></td><td>Fragt beim Druck eines Abgangszeugnisses nicht nach früheren Abschlüssen, wenn der zugehörige Abschluss nicht gefunden wurde.</td></tr><tr><td><code>SchriftenInPDFEinbetten=J</code></td><td>Bettet die verwendete Schrift in die erzeugte PDF-Datei ein. Eine einzelne Zeugnis-PDF-Datei kann dadurch mehrere MB groß werden.</td></tr><tr><td><code>SchriftenInPDFEinbetten=N</code></td><td>Bettet die verwendete Schrift nicht in die erzeugte PDF-Datei ein.</td></tr><tr><td><code>UnicodeInPDFVerwenden=J</code></td><td>Verwendet Unicode-Codierung für Texte in erzeugten PDF-Dateien. Eine einzelne Zeugnis-PDF-Datei kann dadurch mehrere MB groß werden.</td></tr><tr><td><code>UnicodeInPDFVerwenden=N</code></td><td>Verwendet für Texte in erzeugten PDF-Dateien keine Unicode-Codierung.</td></tr></tbody></table><p>Ein Lehrerkürzel wie <code>MUST</code> wird bei den Unterschriften gemäß den Namensoptionen aufgelöst und kann beispielsweise als „Dr. M. Mustermann, StR“ erscheinen. Ein optionaler Funktionszusatz folgt durch Komma getrennt in Klammern, zum Beispiel <code>MUST,(Schulleiterin)</code>.</p><p>Die bisherige Beschreibung nennt bei <code>UnterschriftenVorsitzZAA=I</code> außerdem die abweichende Bezeichnung <code>UnterschriftenZAAText</code>. Prüfen Sie die tatsächlich verwendete Bezeichnung in der mitgelieferten INI-Datei.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Inhalt_%26_Layout_von_Zeugnissen_konfigurieren" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6791.</p>',8)])])}const w=d(u,[["render",a]]);export{A as __pageData,w as default};
